"""Rebuild dated primary-study design gate audit from original first-pass records.

Re-reviewing evidence requires dated edits to this script; do not silently rewrite
original search, effect estimates or PRISMA flows.
"""
from pathlib import Path
import csv, json
from collections import Counter
folder=Path(__file__).resolve().parent
orig=list(csv.DictReader((folder/'fulltext_candidates.csv').open(encoding='utf-8-sig')))
assert len(orig)==28
