assert len(A)==28
out=folder/'primary_design_gates_20261122.csv'
fields=['record_id','original_doi','canonical_doi','programme_id','endpoint_class','design_gate','evidence_level','primary_source_url','reported_design_fact','unresolved_gate','raw_data_retrieved_in_this_pass','new_meta_effect_adopted','screening_note']
with out.open('w',encoding='utf-8',newline='') as f:
 w=csv.DictWriter(f,fieldnames=fields);w.writeheader()
 for i,row in enumerate(orig):
  doi,program,ep,gate,evidence,url,fact,issue=A[i]
  w.writerow({'record_id':row['record_id'],'original_doi':row['doi'],'canonical_doi':doi,'programme_id':program,'endpoint_class':ep,'design_gate':gate,'evidence_level':evidence,'primary_source_url':url,'reported_design_fact':fact,'unresolved_gate':issue,'raw_data_retrieved_in_this_pass':'false','new_meta_effect_adopted':'false','screening_note':row['reason']})
rows=list(csv.DictReader(out.open(encoding='utf-8')))
assert len(rows)==28 and len({r['record_id'] for r in rows})==28
assert {r['record_id'] for r in rows}=={r['record_id'] for r in orig}
assert len({r['programme_id'] for r in rows})==27
assert all(r['new_meta_effect_adopted']=='false' for r in rows)
counts=Counter(x['design_gate'] for x in rows)
print('written',out,len(rows))
print('counts',dict(counts))
with (folder/'primary_design_gates_summary_20261122.json').open('w',encoding='utf-8') as f:
 json.dump({'date':'2026-11-22','report_count':28,'programme_labels_within_queue':27,'counts_by_gate':dict(sorted(counts.items())),'source_review_type':'targeted primary methods review of selected available sources; others remain title/abstract only','fully_independent_eligible_programmes':None,'new_eligible_effects':0,'human_double_screening':False,'verified_programme_duplicate_ids':['MED:38531451','PPR:PPR753662'],'known_existing_programme_ids':['MED:38795821','MED:28139040'],'primary_numeric_analysis_run':False,'source_doi_found':'10.34894/SNKXWK','context_source_doi_found':'10.6084/m9.figshare.29436527'},f,indent=2,ensure_ascii=False)
